import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"Cline","description":"在 Cline 中使用 OpenAI Compatible Provider 接入 Tokeness 的完整配置步骤。","frontmatter":{"title":"Cline","description":"在 Cline 中使用 OpenAI Compatible Provider 接入 Tokeness 的完整配置步骤。"},"headers":[],"relativePath":"integrations/cline.md","filePath":"integrations/cline.md","lastUpdated":1783444478000}'),n={name:"integrations/cline.md"};function d(o,e,l,r,p,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="cline" tabindex="-1">Cline <a class="header-anchor" href="#cline" aria-label="Permalink to &quot;Cline&quot;">​</a></h1><p>Cline 支持 OpenAI Compatible Provider。Tokeness 按 OpenAI 兼容接口接入，配置时填写 Base URL、API Key 和 Model ID。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>API Provider</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model ID</td><td>Tokeness 模型广场中的完整模型名</td></tr></tbody></table><p>如果 Cline 版本中没有 <code>OpenAI Compatible</code>，可以选择 <code>OpenAI</code>，再填写自定义 Base URL。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>在 Tokeness 控制台完成：</p><ol><li>确认钱包余额可用。</li><li>创建 Cline 专用 API Key。</li><li>到模型广场复制模型名。</li><li>打开使用日志，后面用来确认请求。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cline-local</span></span></code></pre></div><p>Cline 是编程 Agent，会读取文件、生成代码、重试任务。单独建 Key，后面看消耗和排查问题都更清楚。</p><h2 id="_2-打开-cline-设置" tabindex="-1">2. 打开 Cline 设置 <a class="header-anchor" href="#_2-打开-cline-设置" aria-label="Permalink to &quot;2. 打开 Cline 设置&quot;">​</a></h2><p>在 VS Code 中打开 Cline 面板，进入设置页。常见入口是 Cline 面板右上角的设置按钮。</p><p>在 Provider 或 API Provider 下拉框中选择：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAI Compatible</span></span></code></pre></div><p>如果界面里只有 OpenAI 选项，检查是否有 Base URL、Custom Base URL 或 API Base 字段。只要能改 Base URL，也可以接入 Tokeness。</p><h2 id="_3-填写-tokeness-配置" tabindex="-1">3. 填写 Tokeness 配置 <a class="header-anchor" href="#_3-填写-tokeness-配置" aria-label="Permalink to &quot;3. 填写 Tokeness 配置&quot;">​</a></h2><p>按下面填写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Base URL: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span>
<span class="line"><span>Model ID: 从 Tokeness 模型广场复制的模型名</span></span></code></pre></div><p>注意：</p><ul><li>Base URL 保留 <code>/v1</code>。</li><li>Model ID 不要自己简写。</li><li>如果 Cline 提供 Verify、Test 或 Save 按钮，保存前先验证一次。</li><li>如果模型列表拉取失败，手动填写 Model ID。</li></ul><h2 id="_4-验证" tabindex="-1">4. 验证 <a class="header-anchor" href="#_4-验证" aria-label="Permalink to &quot;4. 验证&quot;">​</a></h2><p>在 Cline 中发一个只读任务：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请读取当前项目结构，但不要修改文件。最后只总结你看到了哪些顶层目录。</span></span></code></pre></div><p>验证时看三处：</p><ol><li>Cline 是否能正常回复。</li><li>Tokeness 使用日志是否出现请求。</li><li>日志里的 Key、模型名和状态码是否正确。</li></ol><p>第一次测试不要直接让 Cline 大范围改代码。先确认连接、模型和权限都正常，再执行写文件任务。</p><h2 id="_5-写文件前的设置" tabindex="-1">5. 写文件前的设置 <a class="header-anchor" href="#_5-写文件前的设置" aria-label="Permalink to &quot;5. 写文件前的设置&quot;">​</a></h2><p>Cline 会执行文件读取和修改操作。接入 Tokeness 后，工具权限仍然由 Cline 和 VS Code 控制，Tokeness 只负责模型调用。</p><p>写文件前检查：</p><table tabindex="0"><thead><tr><th>项目</th><th>处理</th></tr></thead><tbody><tr><td>Key</td><td>使用 Cline 专用 Key</td></tr><tr><td>额度</td><td>给 Key 设置合适额度</td></tr><tr><td>模型</td><td>选择适合代码任务的模型</td></tr><tr><td>日志</td><td>开着 Tokeness 使用日志，观察是否重复调用</td></tr><tr><td>Git</td><td>开始大改前确认工作区状态</td></tr></tbody></table><h2 id="_6-排查" tabindex="-1">6. 排查 <a class="header-anchor" href="#_6-排查" aria-label="Permalink to &quot;6. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>Verify 失败</td><td>检查 Base URL、Key、模型名</td></tr><tr><td>401 Unauthorized</td><td>重新复制 API Key，确认没有空格</td></tr><tr><td>404 Not Found</td><td>Base URL 应为 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从 Tokeness 模型广场重新复制 Model ID</td></tr><tr><td>Cline 有报错但 Tokeness 无日志</td><td>当前 Provider 没有走 Tokeness</td></tr><tr><td>回复正常但工具调用失败</td><td>换代码能力更强的模型，或缩小任务范围</td></tr><tr><td>消耗偏高</td><td>降低上下文范围，使用独立 Key 限额</td></tr></tbody></table><h2 id="外部文档" tabindex="-1">外部文档 <a class="header-anchor" href="#外部文档" aria-label="Permalink to &quot;外部文档&quot;">​</a></h2><ul><li><a href="https://docs.cline.bot/provider-config/openai-compatible" target="_blank" rel="noreferrer">Cline OpenAI Compatible Provider</a></li><li><a href="https://docs.cline.bot/provider-config/openai" target="_blank" rel="noreferrer">Cline OpenAI Provider Custom Base URL</a></li></ul>`,35)])])}const k=t(n,[["render",d]]);export{b as __pageData,k as default};
